const TOPIC_NAMES = { serverless:'Serverless', lambdas:'Optimización de Lambdas', eventos:'Eventos', multitenancy:'Multi-tenancy', bd:'Bases de Datos', monitoreo:'Monitoreo', servicio:'¿Qué servicio uso?' };

/* ───────────── PREGUNTAS ABIERTAS (las del “Cierre” de cada clase) ───────────── */
const OPEN = [
{ t:'serverless', q:'¿Qué es una arquitectura serverless?', a:'Es construir y ejecutar aplicaciones <b>sin administrar servidores</b>: el proveedor se encarga de la infraestructura (aprovisionar capacidad, aplicar parches, SO, redes) y uno se enfoca en el código. Incluye <b>escalado automático</b>, <b>alta disponibilidad integrada</b> y <b>pago por uso</b>. El código corre como funciones (FaaS) que se ejecutan <b>solo cuando ocurre un evento</b>, en contenedores sin estado.', src:'SV p.5–7' },
{ t:'serverless', q:'¿Cuándo es conveniente usar arquitectura serverless?', a:'Cuando se quiere (1) <b>pasar de la idea al mercado más rápido</b>, lanzando e iterando rápido; (2) <b>disminuir costos</b>, pagando por valor y nunca por exceso de aprovisionamiento; (3) <b>adaptarse a escala</b>, de cero a la demanda máxima automáticamente; (4) <b>crear mejores aplicaciones con más facilidad</b>, centrándose en construir y no en configurar. Es ideal para APIs, backends móviles, procesamiento de imágenes, bots, tareas programadas y análisis de datos.', src:'SV p.5, p.9' },
{ t:'serverless', q:'¿Qué servicios de AWS se pueden usar para arquitectura serverless?', a:'Por capas. <b>Cómputo</b>: Lambda, Fargate. <b>Integración</b>: EventBridge, Step Functions, SQS, SNS, API Gateway, AppSync. <b>Almacén de datos</b>: S3, EFS, DynamoDB, RDS Proxy, Aurora Serverless, Redshift, Neptune, OpenSearch y ElastiCache sin servidor. En los ejemplos también aparecen Kinesis, Amplify, Comprehend y Rekognition.', src:'SV p.11–23' },
{ t:'lambdas', q:'¿Cómo se maneja la memoria RAM y CPU del Lambda?', a:'Se configura la memoria de <b>128 MB a 10 240 MB</b> en incrementos de 1 MB. La CPU no se elige: <b>se asigna en proporción a la memoria</b>. Con <b>1769 MB</b> se obtiene el equivalente a <b>1 vCPU</b> y con 10 GB hasta <b>6 vCPU</b>.', src:'LM p.5–6' },
{ t:'lambdas', q:'¿Cuál es el tiempo de ejecución máximo de Lambda?', a:'<b>900 segundos (15 minutos)</b>.', src:'LM p.8' },
{ t:'lambdas', q:'Explique qué es el Cold Start del Lambda.', a:'Es el <b>delay que se produce cuando se llama a una función inactiva</b>. Lambda corre en contenedores: tras <b>~10 min sin llamadas</b> el contenedor se enfría y se elimina. La siguiente llamada obliga a provisionar una máquina, crear el contenedor y ejecutar el código, lo que puede tardar <b>hasta 5 s</b>. Si la función está caliente (warm), se reutiliza el contenedor y no hay delay. El <b>peso del código y sus dependencias</b> lo aumenta. Fases: Code Download + Start Environment = full cold start; Init = partial; Handler = warm.', src:'LM p.10, p.15' },
{ t:'lambdas', q:'Explique cómo es la concurrencia de ejecución de lambdas.', a:'La concurrencia es el <b>número de solicitudes que la función atiende al mismo tiempo</b>. Por cada solicitud simultánea, Lambda crea un <b>entorno de ejecución separado</b> y escala automáticamente hasta el límite de la cuenta: <b>1000 ejecuciones simultáneas por región</b>, sumando todas las funciones. Si un entorno ya terminó, se reutiliza (sin Init). En el ejemplo, 10 solicitudes usaron 6 entornos.', src:'LM p.12–13' },
{ t:'lambdas', q:'¿Cómo se puede optimizar o mejorar el tiempo de ejecución del Lambda?', a:'(1) <b>Medir</b> el rendimiento con CloudWatch; (2) <b>mantener las funciones calientes</b> con un ping cada n minutos; (3) <b>elegir bien la memoria</b> (también sube la CPU); (4) <b>guardar las dependencias fuera</b> con Lambda Layers; (5) <b>funciones pequeñas y de un solo propósito</b>; (6) <b>simultaneidad aprovisionada</b>: entornos preinicializados que reducen el cold start (con costo extra).', src:'LM p.16' },
{ t:'eventos', q:'¿Qué es una arquitectura basada en eventos?', a:'Usa <b>eventos</b> (cambios de estado o actualizaciones) para <b>desencadenar y comunicar servicios desacoplados</b>. Tiene 3 componentes: <b>productores</b> que publican, <b>enrutadores</b> que filtran y envían, y <b>consumidores</b> que reaccionan. Al estar desacoplados, escalan, se actualizan y se despliegan de forma independiente. El productor no necesita saber quién consume.', src:'EV p.5–8' },
{ t:'eventos', q:'¿Cuándo es conveniente usar arquitectura basada en eventos?', a:'Para la <b>supervisión del estado de los recursos y alertas</b>, el <b>procesamiento en paralelo y la distribución ramificada</b> (fan out), la <b>integración de sistemas heterogéneos</b> y la <b>replicación de datos entre cuentas y regiones</b>. También cuando el sistema debe reaccionar a picos de demanda sin bloquearse ni sobreaprovisionar.', src:'EV p.7, p.10' },
{ t:'eventos', q:'Explique el patrón de diseño pub/sub - fan out.', a:'Para enviar <b>un mensaje a muchos receptores</b>, en lugar de que el productor llame a cada uno (integración directa, síncrona y acoplada), el productor <b>publica una sola vez</b> en un <b>tema SNS</b> (o en un bus de <b>EventBridge</b> con reglas) y cada suscriptor recibe una copia: comunicación <b>asíncrona y desacoplada</b>. Variante <b>SNS + SQS</b>: el tema reparte a una <b>cola SQS por servicio</b> (p. ej. Fraud y Shipping) y cada uno consume a su ritmo.', src:'EV p.18–21' },
{ t:'eventos', q:'¿Qué servicios de AWS se pueden usar para arquitectura basada en eventos?', a:'Como enrutadores: <b>Amazon EventBridge</b> (buses de eventos; reacciona a eventos de SaaS, AWS o apps propias; reglas que filtran sobre todo el cuerpo) y <b>Amazon SNS</b> (temas; alto rendimiento, baja latencia, difusión masiva, independiente del esquema). Además <b>SQS</b> para colas y <b>Lambda</b> como consumidor. Publicadores de SNS: CloudWatch Alarms, S3, DynamoDB, Auto Scaling, etc.; suscriptores: SQS, Lambda, Firehose, email, SMS, HTTP(S).', src:'EV p.12, p.22' },
{ t:'multitenancy', q:'¿Qué es Multi-tenancy o tenencia múltiple?', a:'Es un principio de arquitectura donde <b>varios clientes (tenants) usan los mismos recursos</b> y <b>la misma instancia de software</b>, pero <b>no saben de la existencia de los otros</b> y <b>sus datos están totalmente separados</b>, así que la app se ve como hecha exclusivamente para cada uno. Es característica de IaaS, PaaS, SaaS, contenedores y serverless en la nube pública.', src:'MT p.7–8' },
{ t:'multitenancy', q:'Explique una diferencia entre Single tenant vs Multi tenant.', a:'<b>Costo vs seguridad</b>: single tenant da a cada cliente un entorno dedicado (SW, HW, BD), con <b>mayor costo</b> y <b>mayor seguridad</b>; multi tenant comparte la aplicación y el hardware, con <b>menor costo</b> y <b>menor seguridad</b>. Otras diferencias: en single tenant se puede modificar el software a medida; en multi tenant el rendimiento puede afectarse por el uso intensivo de otros clientes.', src:'MT p.10' },
{ t:'multitenancy', q:'Explique un patrón de diseño para bases de datos Multi-tenancy.', a:'<b>Patrón 1 – Single, Shared Database Schema</b>: un solo esquema; cada tabla tiene un campo <code>TENANT_ID</code> y se filtra con <code>WHERE TENANT_ID = ?</code>. (Otros: <b>Patrón 2</b>, una BD con un schema por tenant, donde el reto es conectarse al schema correcto; <b>Patrón 3</b>, una BD por tenant, con el mayor aislamiento y seguridad pero el mayor esfuerzo de configuración.)', src:'MT p.12–14' },
{ t:'bd', q:'¿Qué es una Base de Datos SQL?', a:'Es una base de datos <b>relacional</b>: organiza la información en <b>tablas</b> con una <b>estructura definida</b> en el diseño, se relacionan con joins y está diseñada para <b>evitar la redundancia</b>. La actualización es más segura, por eso sirve para datos consistentes (financieros). <b>Escala verticalmente</b>. Motores: Oracle, SQL Server, MySQL, SQLite, MariaDB, PostgreSQL.', src:'BD p.5, p.8, p.15' },
{ t:'bd', q:'¿Qué es una Base de Datos NoSQL?', a:'Es una base de datos <b>no relacional</b>: <b>no usa tablas</b> (documentos, clave/valor, familias de columnas), su estructura puede ser <b>dinámica</b> y <b>permite redundancia</b> para consultar más rápido. <b>Prioriza la velocidad sobre la integridad</b> y <b>escala horizontalmente</b>. Motores: MongoDB, Cosmos DB, ArangoDB, Firestore, DynamoDB, Redis.', src:'BD p.5, p.12, p.15' },
{ t:'bd', q:'Comparar Base de Datos SQL vs NoSQL y en qué casos utilizar cada una.', a:'<b>SQL</b>: tablas, estructura fija, mínima redundancia, consistencia y escala vertical. Úsala para datos que <b>no admiten error</b> (financieros, sector empresarial; web, mobile, enterprise, data mart). <b>NoSQL</b>: documentos, estructura dinámica, redundancia, velocidad y escala horizontal. Úsala para <b>grandes volúmenes</b> y <b>respuesta rápida</b> (redes sociales, gaming, IoT, web, mobile).', src:'BD p.15–16' },
{ t:'monitoreo', q:'¿Qué es Monitoreo?', a:'Una <b>estrategia de gestión</b>: cualquier flujo de trabajo operativo que evalúa los recursos informáticos y las aplicaciones para obtener <b>visibilidad del rendimiento, el estado y la disponibilidad</b> de los servicios.', src:'MO p.5' },
{ t:'monitoreo', q:'¿Qué diferencias hay entre Reactivo y Proactivo?', a:'<b>Reactivo (monitoreo)</b>: pregunta “¿mi sistema funciona?”, indica <b>QUÉ</b> sucede y detecta <b>problemas conocidos</b> con métricas y registros. <b>Proactivo (observabilidad)</b>: pregunta “¿qué está haciendo mi sistema?”, explica <b>POR QUÉ</b> pasa, enriquece la información y puede <b>predecir</b> comportamientos usando eventos, métricas, registros y trazas. La observabilidad es la evolución del monitoreo.', src:'MO p.7' },
{ t:'monitoreo', q:'¿Qué métricas y herramientas hay en AWS?', a:'<b>Amazon CloudWatch</b>: monitoreo y observabilidad que recopila <b>registros, métricas y eventos</b> de más de 70 servicios (EC2, DynamoDB, S3, ECS, EKS, Lambda) y de entornos locales. Ofrece <b>paneles</b>, <b>alarmas por umbrales</b>, <b>acciones automáticas</b> (notificación, Auto Scaling), <b>CloudWatch Events</b> (dispara Lambda, SNS, CloudFormation) y <b>Logs Insights</b>, con métricas de 1 s y 15 meses de retención. Funciona en 4 etapas: Collect → Monitor → Act → Analyze.', src:'MO p.9–12' },
];

